// Flujo C — REEMPLAZAR TODO el código del nodo Code: Calcular Fechas Semanal.
// Ejecución: lunes 8:00 → reporte de la semana anterior (lun–dom).
const FECHA_EJECUCION_PRUEBA = null;

const valorPrueba =
  FECHA_EJECUCION_PRUEBA == null ? "" : String(FECHA_EJECUCION_PRUEBA).trim();
if (valorPrueba && !/^\d{4}-\d{2}-\d{2}$/.test(valorPrueba)) {
  throw new Error("FECHA_EJECUCION_PRUEBA debe ser YYYY-MM-DD o null");
}

const hoyEfectivo = valorPrueba
  ? new Date(`${valorPrueba}T12:00:00Z`)
  : new Date();
if (Number.isNaN(hoyEfectivo.getTime())) {
  throw new Error("Fecha inválida en FECHA_EJECUCION_PRUEBA");
}

const addDaysUtc = (dateStr, days) => {
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().split("T")[0];
};

const fecha_ejecucion = hoyEfectivo.toISOString().split("T")[0];
const semana_fin = addDaysUtc(fecha_ejecucion, -1);
const semana_inicio = addDaysUtc(semana_fin, -6);

return [
  {
    json: {
      fecha_ejecucion,
      semana_inicio,
      semana_fin,
      fecha_prueba_usada: valorPrueba || null,
    },
  },
];

// Flujo C — nodo Code: Ventana Efectiva Semanal.
// Intersección semana calendario × periodo de la orden (semana parcial).
const orden = $("Split In Batches - Por Campaña").item.json;
const fechas = $("Code: Calcular Fechas Semanal").first().json;

const { semana_inicio, semana_fin, fecha_ejecucion } = fechas;

const maxDate = (a, b) => (a > b ? a : b);
const minDate = (a, b) => (a < b ? a : b);

const eval_inicio = maxDate(semana_inicio, orden.periodo_inicio);
const eval_fin = minDate(semana_fin, orden.periodo_fin);

const diasInclusivos = (inicio, fin) => {
  const start = new Date(`${inicio}T00:00:00Z`);
  const end = new Date(`${fin}T00:00:00Z`);
  const ms = end.getTime() - start.getTime();
  if (ms < 0) return 0;
  return Math.floor(ms / (24 * 60 * 60 * 1000)) + 1;
};

const skip = eval_inicio > eval_fin;
const dias_efectivos = skip ? 0 : diasInclusivos(eval_inicio, eval_fin);

return [
  {
    json: {
      skip,
      orden,
      semana_inicio,
      semana_fin,
      eval_inicio,
      eval_fin,
      dias_efectivos,
      fecha_ejecucion,
    },
  },
];

// Flujo C — nodo Code: Filtrar Detecciones (misma lógica que Flujo B).
const response = $input.first().json;
const detecciones = response.data || [];
const orden = $("Split In Batches - Por Campaña").item.json;
const ventana = $("Code: Ventana Efectiva Semanal").item.json;
const meta = response.meta || {};

const parsearFechaRFC2822 = (fechaStr) => {
  if (!fechaStr) return null;
  try {
    const fecha = new Date(fechaStr);
    if (isNaN(fecha.getTime())) return null;
    const año = fecha.getFullYear();
    const mes = String(fecha.getMonth() + 1).padStart(2, "0");
    const dia = String(fecha.getDate()).padStart(2, "0");
    return `${año}-${mes}-${dia}`;
  } catch {
    return null;
  }
};

const eval_inicio = ventana.eval_inicio;
const eval_fin = ventana.eval_fin;
const acum_inicio = orden.periodo_inicio;
const acum_fin = eval_fin;

const ordenSinSpot = !orden.spot_id && !orden.spot_name;
const matchPorClienteOCampaña = (d) => {
  if (!d.spot_name) return false;
  const sn = d.spot_name.toLowerCase();
  if (orden.cliente && sn.includes(orden.cliente.toLowerCase())) return true;
  if (orden.campaña && sn.includes(orden.campaña.toLowerCase())) return true;
  return false;
};

const coincideSpot = (d) =>
  (orden.spot_name &&
    d.spot_name &&
    (d.spot_name.toLowerCase().includes(orden.spot_name.toLowerCase()) ||
      orden.spot_name.toLowerCase().includes(d.spot_name.toLowerCase()))) ||
  (orden.spot_id && d.spot_id && d.spot_id === orden.spot_id) ||
  (orden.emisora &&
    d.channel_name &&
    (d.channel_name.toLowerCase().includes(orden.emisora.toLowerCase()) ||
      orden.emisora.toLowerCase().includes(d.channel_name.toLowerCase()))) ||
  (orden.emisora &&
    d.channel_id &&
    orden.channel_id &&
    d.channel_id === orden.channel_id) ||
  (ordenSinSpot && matchPorClienteOCampaña(d));

const filtradas = detecciones.filter((d) => {
  const fechaStr = parsearFechaRFC2822(d.datetime_utc);
  if (!fechaStr) return false;
  const enRangoAcum =
    fechaStr >= acum_inicio && fechaStr <= acum_fin;
  if (!enRangoAcum) return false;
  return coincideSpot(d);
});

return [
  {
    json: {
      detecciones_filtradas: filtradas,
      total_filtradas: filtradas.length,
      orden,
      eval_inicio,
      eval_fin,
      acum_inicio,
      acum_fin,
      ...ventana,
    },
  },
];

// Compartido: Flujo B/C y scripts de prueba (sin imports en n8n).
// Mantener alineado con src/lib/meta-campana.ts

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

function isValidDateOnly(dateStr) {
  if (!dateStr || !DATE_ONLY.test(dateStr)) return false;
  const d = new Date(`${dateStr}T00:00:00Z`);
  return !Number.isNaN(d.getTime());
}

function addDaysUtc(dateStr, days) {
  if (!isValidDateOnly(dateStr)) return dateStr;
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  const next = d.toISOString().split("T")[0];
  return isValidDateOnly(next) ? next : dateStr;
}

function isoWeekdayFromDateStr(dateStr) {
  const d = new Date(`${dateStr}T12:00:00Z`);
  const js = d.getUTCDay();
  return js === 0 ? 7 : js;
}

function diasInclusivos(inicio, fin) {
  const start = new Date(`${inicio}T00:00:00Z`);
  const end = new Date(`${fin}T00:00:00Z`);
  const ms = end.getTime() - start.getTime();
  if (ms < 0) return 0;
  return Math.floor(ms / (24 * 60 * 60 * 1000)) + 1;
}

function parseTramosCuotas(raw) {
  if (!Array.isArray(raw) || raw.length === 0) return null;
  const tramos = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const desde = String(item.desde ?? "");
    const hasta = String(item.hasta ?? "");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(desde) || !/^\d{4}-\d{2}-\d{2}$/.test(hasta)) {
      continue;
    }
    const dias = Array.isArray(item.dias_semana)
      ? item.dias_semana
          .map((d) => Number(d))
          .filter((d) => d >= 1 && d <= 7)
      : [];
    const cuñas = Number(item.cuñas_por_dia ?? item.cunias_por_dia);
    if (!Number.isFinite(cuñas) || cuñas < 0) continue;
    tramos.push({
      desde,
      hasta,
      dias_semana: dias,
      cuñas_por_dia: cuñas,
    });
  }
  return tramos.length > 0 ? tramos : null;
}

function cuniasContratadasDelDia(orden, dateStr) {
  if (dateStr < orden.periodo_inicio || dateStr > orden.periodo_fin) {
    return 0;
  }

  const tramos = parseTramosCuotas(orden.tramos_cuotas);
  if (tramos) {
    let sum = 0;
    for (const tramo of tramos) {
      if (dateStr >= tramo.desde && dateStr <= tramo.hasta) {
        const dow = isoWeekdayFromDateStr(dateStr);
        if (tramo.dias_semana.includes(dow)) {
          sum += tramo.cuñas_por_dia;
        }
      }
    }
    return sum;
  }

  return Number(orden.cuñas_diarias) || 0;
}

function metaAcumuladaHasta(orden, finDate) {
  if (
    !isValidDateOnly(orden.periodo_inicio) ||
    !isValidDateOnly(orden.periodo_fin) ||
    !finDate ||
    !isValidDateOnly(finDate) ||
    finDate < orden.periodo_inicio
  ) {
    return 0;
  }
  const finEfectivo =
    finDate > orden.periodo_fin ? orden.periodo_fin : finDate;

  let acum = 0;
  let d = orden.periodo_inicio;
  let guard = 0;
  while (d <= finEfectivo && guard < 4000) {
    acum += cuniasContratadasDelDia(orden, d);
    const next = addDaysUtc(d, 1);
    if (next <= d) break;
    d = next;
    guard += 1;
  }

  const cap = Number(orden.total_contratadas) || 0;
  if (cap <= 0) return acum;
  return Math.min(acum, cap);
}

function contratadasEnRango(orden, inicio, fin) {
  if (
    !isValidDateOnly(inicio) ||
    !isValidDateOnly(fin) ||
    fin < inicio
  ) {
    return 0;
  }
  let sum = 0;
  let d = inicio;
  let guard = 0;
  while (d <= fin && guard < 4000) {
    if (d >= orden.periodo_inicio && d <= orden.periodo_fin) {
      sum += cuniasContratadasDelDia(orden, d);
    }
    const next = addDaysUtc(d, 1);
    if (next <= d) break;
    d = next;
    guard += 1;
  }
  return sum;
}

function calcularEstadoSemanal(
  transmitidasSemana,
  contratadasSemana,
  cuotaSemanaAgotada,
) {
  if (contratadasSemana <= 0) {
    if (cuotaSemanaAgotada) {
      return {
        estado: transmitidasSemana > 0 ? "en_compensacion" : "cumple",
        estado_label:
          transmitidasSemana > 0
            ? "En compensación (cuota cumplida)"
            : "Cuota cumplida",
        porcentaje_cumplimiento: "—",
        cuota_semana_agotada: true,
      };
    }
    if (transmitidasSemana === 0) {
      return {
        estado: "cumple",
        estado_label: "Sin meta esta semana",
        porcentaje_cumplimiento: "—",
        cuota_semana_agotada: false,
      };
    }
    return {
      estado: "en_compensacion",
      estado_label: "En compensación",
      porcentaje_cumplimiento: "—",
      cuota_semana_agotada: false,
    };
  }

  let estado = "atrasado";
  if (transmitidasSemana >= contratadasSemana) {
    estado =
      transmitidasSemana > contratadasSemana
        ? "en_compensacion"
        : "cumple";
  }

  const estadoLabel =
    estado === "cumple"
      ? "Cumple"
      : estado === "atrasado"
        ? "Atrasado"
        : "En compensación";

  const porcentaje = (
    (transmitidasSemana / contratadasSemana) *
    100
  ).toFixed(1);

  return {
    estado,
    estado_label: estadoLabel,
    porcentaje_cumplimiento: porcentaje,
    cuota_semana_agotada: false,
  };
}

function totalContratadasCalculado(orden) {
  if (
    !isValidDateOnly(orden.periodo_inicio) ||
    !isValidDateOnly(orden.periodo_fin) ||
    orden.periodo_fin < orden.periodo_inicio
  ) {
    return 0;
  }
  return contratadasEnRango(
    orden,
    orden.periodo_inicio,
    orden.periodo_fin,
  );
}

// Flujo C — nodo Code: Calcular Métricas Semanal.

// Requiere scripts/meta-campana.js (concatenado en build-flujo-c.mjs).

const data = $input.first().json;

const detecciones = data.detecciones_filtradas || [];

const orden = data.orden;

const eval_inicio = data.eval_inicio;

const eval_fin = data.eval_fin;

const semana_inicio = data.semana_inicio;

const semana_fin = data.semana_fin;

const dias_efectivos = data.dias_efectivos;

const fecha_ejecucion = data.fecha_ejecucion;



const parsearFechaRFC2822 = (fechaStr) => {

  if (!fechaStr) return null;

  const fecha = new Date(fechaStr);

  if (isNaN(fecha.getTime())) return null;

  const año = fecha.getUTCFullYear();

  const mes = String(fecha.getUTCMonth() + 1).padStart(2, "0");

  const dia = String(fecha.getUTCDate()).padStart(2, "0");

  return `${año}-${mes}-${dia}`;

};



const totalContratadasOrden = Number(orden.total_contratadas || 0);

const dayBeforeEvalInicio = addDaysUtc(eval_inicio, -1);

const metaAntesSemana =

  eval_inicio <= orden.periodo_inicio

    ? 0

    : metaAcumuladaHasta(orden, dayBeforeEvalInicio);

const contratadas_semana = contratadasEnRango(orden, eval_inicio, eval_fin);

const cuotaSemanaAgotada =

  contratadas_semana <= 0 &&

  totalContratadasOrden > 0 &&

  metaAntesSemana >= totalContratadasOrden;



let transmitidas_semana = 0;

let transmitidas_acumuladas = 0;



detecciones.forEach((d) => {

  const fechaStr = parsearFechaRFC2822(d.datetime_utc);

  if (!fechaStr) return;

  if (fechaStr >= eval_inicio && fechaStr <= eval_fin) {

    transmitidas_semana += 1;

  }

  if (fechaStr >= orden.periodo_inicio && fechaStr <= eval_fin) {

    transmitidas_acumuladas += 1;

  }

});



const faltantes_semana = Math.max(0, contratadas_semana - transmitidas_semana);

const excedentes_semana = Math.max(0, transmitidas_semana - contratadas_semana);



const metaAcumuladaCampana = metaAcumuladaHasta(orden, eval_fin);

const faltantes_acumulados = Math.max(

  0,

  metaAcumuladaCampana - transmitidas_acumuladas,

);



const estadoResult = calcularEstadoSemanal(

  transmitidas_semana,

  contratadas_semana,

  cuotaSemanaAgotada,

);



const telefono = String(orden.telefono_cliente ?? "").trim();

const email = String(orden.email_cliente ?? "").trim();



return [

  {

    json: {

      orden,

      semana_inicio,

      semana_fin,

      eval_inicio,

      eval_fin,

      dias_efectivos,

      fecha_ejecucion,

      transmitidas_semana,

      contratadas_semana,

      transmitidas_acumuladas,

      faltantes_semana,

      excedentes_semana,

      faltantes_acumulados,

      estado: estadoResult.estado,

      estado_label: estadoResult.estado_label,

      porcentaje_cumplimiento: estadoResult.porcentaje_cumplimiento,

      cuota_semana_agotada: estadoResult.cuota_semana_agotada,

      tiene_telefono: telefono.length > 0,

      tiene_email: email.length > 0,

      telefono_destino: telefono || null,

      email_destino: email || null,

      total_contratadas_orden: totalContratadasOrden,

      meta_acumulada_campana: metaAcumuladaCampana,

    },

  },

];

